import{_ as e}from"./chunks/26c01b321adb77cd693d3070f7af8528.Cmwa54Gr.js";import{_ as a,c as d,a2 as r,o}from"./chunks/framework.BnrAgU0Y.js";const g=JSON.parse('{"title":"Langflow 中的代理组件","description":"Langflow 中的代理组件","frontmatter":{"title":"Langflow 中的代理组件","description":"Langflow 中的代理组件","layout":"doc"},"headers":[],"relativePath":"langflow/components-agents.md","filePath":"langflow/components-agents.md"}'),h={name:"langflow/components-agents.md"};function n(l,t,i,s,u,p){return o(),d("div",null,t[0]||(t[0]=[r('<h1 id="langflow-中的代理组件" tabindex="-1">Langflow 中的代理组件 <a class="header-anchor" href="#langflow-中的代理组件" aria-label="Permalink to &quot;Langflow 中的代理组件&quot;">​</a></h1><p>代理组件定义了在流中AI代理的行为和能力。</p><p>代理使用大型语言模型（LLMs）作为推理引擎，以决定使用哪个连接的工具组件来解决问题。</p><p>在代理功能中的工具基本上是代理可以调用以执行任务或访问外部资源的函数。一个函数会被封装成一个 <code>Tool</code>（工具）对象，并具有代理能够理解的通用接口。代理通过工具注册来获知工具，即在代理初始化时提供可用工具的列表。<code>Tool</code> 对象的描述告诉代理该工具可以做什么。</p><p>然后，代理使用连接的LLM来对问题进行推理，以决定哪个工具是最适合该任务的。</p><h2 id="在流程中使用代理" tabindex="-1">在流程中使用代理 <a class="header-anchor" href="#在流程中使用代理" aria-label="Permalink to &quot;在流程中使用代理&quot;">​</a></h2><p><a href="./../starter-projects-simple-agent.html">简单代理入门项目</a>使用连接到 URL 和计算器工具的<a href="#agent-component">代理组件</a>来回答用户的问题。OpenAI LLM 作为代理的大脑，决定使用哪个工具。工具通过<strong>Tools</strong>端口连接到代理组件。</p><p><img src="'+e+'" alt="Simple agent starter flow"></p><p>对于多代理示例，请参见<a href="./agents-tool-calling-agent-component.html">创建一个解决问题的代理</a>。</p><h2 id="agent-组件" tabindex="-1">Agent 组件 <a class="header-anchor" href="#agent-组件" aria-label="Permalink to &quot;Agent 组件&quot;">​</a></h2><p>该组件创建一个代理，可以使用工具根据给定指令回答问题并执行任务。</p><p>该组件包括一个 LLM 模型集成、一个系统消息提示，以及一个 <strong>Tools</strong>（工具）端口用于连接工具以扩展其功能。</p><p>欲了解关于此组件的更多信息，请参阅 <a href="/bllm/agents-tool-calling-agent-component.html">工具调用代理文档</a>。</p><h3 id="inputs" tabindex="-1">Inputs <a class="header-anchor" href="#inputs" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>agent_llm</td><td>Dropdown</td><td>语言模型的提供商，代理将使用该模型生成响应。选项包括 OpenAI 和其他提供商，或自定义。</td></tr><tr><td>system_prompt</td><td>String</td><td>系统提示：用于指导代理行为的初始指令和上下文。</td></tr><tr><td>tools</td><td>List</td><td>代理可用的工具列表。</td></tr><tr><td>input_value</td><td>String</td><td>代理处理的输入任务或问题。</td></tr><tr><td>add_current_date_tool</td><td>Boolean</td><td>如果为 true，添加一个返回当前日期的工具给代理。</td></tr><tr><td>memory</td><td>Memory</td><td>可选的内存配置，用于维护对话历史记录。</td></tr><tr><td>max_iterations</td><td>Integer</td><td>代理可以执行的最大迭代次数。</td></tr><tr><td>handle_parsing_errors</td><td>Boolean</td><td>是否在代理执行过程中处理解析错误。</td></tr><tr><td>verbose</td><td>Boolean</td><td>启用详细输出以进行详细日志记录。</td></tr></tbody></table><h3 id="outputs" tabindex="-1">Outputs <a class="header-anchor" href="#outputs" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>response</td><td>Message</td><td>代理程序对给定输入任务的响应。</td></tr></tbody></table><h2 id="csv-agent" tabindex="-1">CSV Agent <a class="header-anchor" href="#csv-agent" aria-label="Permalink to &quot;CSV Agent&quot;">​</a></h2><p>此组件通过CSV文件和LLM（大语言模型）创建一个CSV代理。</p><h3 id="inputs-1" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-1" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>llm</td><td>LanguageModel</td><td>用于Agent（代理）的语言模型</td></tr><tr><td>path</td><td>File</td><td>CSV文件的路径</td></tr><tr><td>agent_type</td><td>String</td><td>创建代理的类型（zero-shot-react-description, openai-functions, 或 openai-tools）</td></tr></tbody></table><h3 id="outputs-1" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-1" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>agent</td><td>AgentExecutor</td><td>CSV agent 实例</td></tr></tbody></table><h2 id="crewai-agent" tabindex="-1">CrewAI Agent <a class="header-anchor" href="#crewai-agent" aria-label="Permalink to &quot;CrewAI Agent&quot;">​</a></h2><p>该组件代表CrewAI的一个Agent（代理），允许在一个团队中创建具有定义的角色、目标和能力的专业AI代理。</p><p>欲了解更多信息，请参阅 <a href="https://docs.crewai.com/core-concepts/Agents/" target="_blank" rel="noreferrer">CrewAI 文档</a>。</p><h3 id="inputs-2" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-2" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>role</td><td>Role</td><td>代理的角色</td></tr><tr><td>goal</td><td>Goal</td><td>代理的目标</td></tr><tr><td>backstory</td><td>Backstory</td><td>代理的背景故事</td></tr><tr><td>tools</td><td>Tools</td><td>代理可使用的工具</td></tr><tr><td>llm</td><td>Language Model</td><td>运行代理的语言模型</td></tr><tr><td>memory</td><td>Memory</td><td>代理是否应该拥有记忆</td></tr><tr><td>verbose</td><td>Verbose</td><td>启用详细输出</td></tr><tr><td>allow_delegation</td><td>Allow Delegation</td><td>代理是否被允许将任务委派给其他代理</td></tr><tr><td>allow_code_execution</td><td>Allow Code Execution</td><td>代理是否被允许执行代码</td></tr><tr><td>kwargs</td><td>kwargs</td><td>为代理提供的附加关键字参数</td></tr></tbody></table><h3 id="outputs-2" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-2" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>output</td><td>Agent</td><td>The constructed CrewAI Agent object</td></tr></tbody></table><h2 id="hierarchical-crew" tabindex="-1">Hierarchical Crew <a class="header-anchor" href="#hierarchical-crew" aria-label="Permalink to &quot;Hierarchical Crew&quot;">​</a></h2><p>该组件代表一组代理，负责管理他们在层次结构中的协作方式和应执行的任务。该组件允许创建一个团队，由经理监督任务执行。</p><p>欲了解更多信息，请参见 <a href="https://docs.crewai.com/how-to/Hierarchical/" target="_blank" rel="noreferrer">CrewAI 文档</a>。</p><h3 id="inputs-3" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-3" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>agents</td><td>Agents</td><td>表示团队成员的 Agent 对象列表</td></tr><tr><td>tasks</td><td>Tasks</td><td>表示要执行任务的 HierarchicalTask 对象列表</td></tr><tr><td>manager_llm</td><td>Manager LLM</td><td>管理代理的语言模型（可选）</td></tr><tr><td>manager_agent</td><td>Manager Agent</td><td>作为管理者的特定代理（可选）</td></tr><tr><td>verbose</td><td>Verbose</td><td>启用详细输出以进行详细日志记录</td></tr><tr><td>memory</td><td>Memory</td><td>指定团队的内存配置</td></tr><tr><td>use_cache</td><td>Use Cache</td><td>启用结果缓存</td></tr><tr><td>max_rpm</td><td>Max RPM</td><td>设置每分钟的最大请求数</td></tr><tr><td>share_crew</td><td>Share Crew</td><td>决定是否在代理之间共享团队信息</td></tr><tr><td>function_calling_llm</td><td>Function Calling LLM</td><td>为函数调用指定的语言模型</td></tr></tbody></table><h3 id="outputs-3" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-3" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>crew</td><td>Crew</td><td>构建的 Crew 对象，具备层级任务执行功能</td></tr></tbody></table><h2 id="json-agent" tabindex="-1">JSON Agent <a class="header-anchor" href="#json-agent" aria-label="Permalink to &quot;JSON Agent&quot;">​</a></h2><p>该组件从一个 JSON 或 YAML 文件和一个 LLM（大型语言模型）中创建一个 JSON agent。</p><h3 id="inputs-4" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-4" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>llm</td><td>LanguageModel</td><td>用于代理的语言模型</td></tr><tr><td>path</td><td>File</td><td>JSON 或 YAML 文件的路径</td></tr></tbody></table><h3 id="输出" tabindex="-1">输出 <a class="header-anchor" href="#输出" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>agent</td><td>AgentExecutor</td><td>JSON agent 实例</td></tr></tbody></table><h2 id="openai-工具代理" tabindex="-1">OpenAI 工具代理 <a class="header-anchor" href="#openai-工具代理" aria-label="Permalink to &quot;OpenAI 工具代理&quot;">​</a></h2><p>该组件使用 LangChain 创建一个 OpenAI 工具代理。</p><p>欲了解更多信息，请参阅 <a href="https://python.langchain.com/v0.1/docs/modules/agents/agent_types/openai_tools/" target="_blank" rel="noreferrer">LangChain 文档</a>。</p><h3 id="inputs-5" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-5" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>llm</td><td>LanguageModel</td><td>用于代理的语言模型（必须支持工具）</td></tr><tr><td>system_prompt</td><td>String</td><td>代理的系统提示</td></tr><tr><td>user_prompt</td><td>String</td><td>用户提示模板（必须包含 &#39;input&#39; 键）</td></tr><tr><td>chat_history</td><td>List[Data]</td><td>可选的代理聊天历史</td></tr><tr><td>tools</td><td>List[Tool]</td><td>提供给代理的工具列表</td></tr></tbody></table><h3 id="outputs-4" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-4" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>agent</td><td>AgentExecutor</td><td>OpenAI工具代理实例</td></tr></tbody></table><h2 id="openapi-agent" tabindex="-1">OpenAPI Agent <a class="header-anchor" href="#openapi-agent" aria-label="Permalink to &quot;OpenAPI Agent&quot;">​</a></h2><p>该组件创建一个 OpenAPI Agent，用于与由 OpenAPI 规范定义的 API 进行交互。</p><p>欲了解更多信息，请参阅 LangChain 文档中的 OpenAPI Agents 部分。</p><h3 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>llm</td><td>LanguageModel</td><td>用于代理的语言模型</td></tr><tr><td>path</td><td>文件</td><td>OpenAPI 规范文件的路径（JSON 或 YAML 格式）</td></tr><tr><td>allow_dangerous_requests</td><td>布尔值</td><td>是否允许潜在危险的 API 请求</td></tr></tbody></table><h3 id="输出-1" tabindex="-1">输出 <a class="header-anchor" href="#输出-1" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>agent</td><td>AgentExecutor</td><td>OpenAPI Agent 实例</td></tr></tbody></table><h2 id="sql-agent" tabindex="-1">SQL Agent <a class="header-anchor" href="#sql-agent" aria-label="Permalink to &quot;SQL Agent&quot;">​</a></h2><p>该组件用于创建一个SQL Agent，以与SQL数据库进行交互。</p><h3 id="输入-1" tabindex="-1">输入 <a class="header-anchor" href="#输入-1" aria-label="Permalink to &quot;输入&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>llm</td><td>LanguageModel</td><td>用于代理的语言模型</td></tr><tr><td>database_uri</td><td>String</td><td>要连接的 SQL 数据库的 URI（统一资源标识符）</td></tr><tr><td>extra_tools</td><td>List[Tool]</td><td>提供给代理的附加工具（可选）</td></tr></tbody></table><h3 id="outputs-5" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-5" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>agent</td><td>AgentExecutor</td><td>SQL Agent 实例</td></tr></tbody></table><h2 id="sequential-crew" tabindex="-1">Sequential Crew <a class="header-anchor" href="#sequential-crew" aria-label="Permalink to &quot;Sequential Crew&quot;">​</a></h2><p>这个组件代表一组顺序执行任务的代理（agents）。该组件允许创建一个按特定顺序执行任务的团队。</p><p>有关更多信息，请参阅 <a href="https://docs.crewai.com/how-to/Sequential/" target="_blank" rel="noreferrer">CrewAI 文档</a>。</p><h3 id="inputs-6" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-6" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>tasks</td><td>Tasks</td><td>执行任务的 SequentialTask 对象列表</td></tr><tr><td>verbose</td><td>Verbose</td><td>启用详细输出以进行详细日志记录</td></tr><tr><td>memory</td><td>Memory</td><td>指定 crew（团队）的内存配置</td></tr><tr><td>use_cache</td><td>Use Cache</td><td>启用结果缓存</td></tr><tr><td>max_rpm</td><td>Max RPM</td><td>设置每分钟的最大请求数</td></tr><tr><td>share_crew</td><td>Share Crew</td><td>决定是否在 agent（代理）之间共享 crew（团队）信息</td></tr><tr><td>function_calling_llm</td><td>Function Calling LLM</td><td>指定用于函数调用的语言模型</td></tr></tbody></table><h3 id="outputs-6" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-6" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>crew</td><td>Crew</td><td>构建的 Crew 对象，具有顺序任务执行功能</td></tr></tbody></table><h2 id="sequential-task-agent" tabindex="-1">Sequential task agent <a class="header-anchor" href="#sequential-task-agent" aria-label="Permalink to &quot;Sequential task agent&quot;">​</a></h2><p>该组件创建一个 CrewAI 任务及其相关代理，允许定义具有特定代理角色和能力的顺序任务。</p><p>欲了解更多信息，请参阅 <a href="https://docs.crewai.com/how-to/Sequential/" target="_blank" rel="noreferrer">CrewAI 文档</a>。</p><h3 id="inputs-7" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-7" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>role</td><td>Role</td><td>代理的角色</td></tr><tr><td>goal</td><td>Goal</td><td>代理的目标</td></tr><tr><td>backstory</td><td>Backstory</td><td>代理的背景故事</td></tr><tr><td>tools</td><td>Tools</td><td>代理可使用的工具</td></tr><tr><td>llm</td><td>Language Model</td><td>将运行代理的语言模型</td></tr><tr><td>memory</td><td>Memory</td><td>代理是否应该有记忆</td></tr><tr><td>verbose</td><td>Verbose</td><td>启用详细输出</td></tr><tr><td>allow_delegation</td><td>Allow Delegation</td><td>代理是否被允许将任务委派给其他代理</td></tr><tr><td>allow_code_execution</td><td>Allow Code Execution</td><td>代理是否被允许执行代码</td></tr><tr><td>agent_kwargs</td><td>Agent kwargs</td><td>代理的附加关键字参数</td></tr><tr><td>task_description</td><td>Task Description</td><td>详细描述任务的目的和执行方式</td></tr><tr><td>expected_output</td><td>Expected Task Output</td><td>明确定义任务预期结果</td></tr><tr><td>async_execution</td><td>Async Execution</td><td>指示异步任务执行的布尔标志</td></tr><tr><td>previous_task</td><td>Previous Task</td><td>序列中的前一个任务（用于链式任务）</td></tr></tbody></table><h3 id="outputs-7" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-7" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>task_output</td><td>Sequential Task</td><td>创建的任务对象<code>SequentialTask</code>列表</td></tr></tbody></table><h2 id="工具调用代理" tabindex="-1">工具调用代理 <a class="header-anchor" href="#工具调用代理" aria-label="Permalink to &quot;工具调用代理&quot;">​</a></h2><p>该组件使用 LangChain 创建一个工具调用代理。</p><h3 id="inputs-8" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-8" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>llm</td><td>LanguageModel</td><td>用于代理的语言模型</td></tr><tr><td>system_prompt</td><td>String</td><td>代理的系统提示</td></tr><tr><td>user_prompt</td><td>String</td><td>用户提示模板（必须包含 &#39;input&#39; 键）</td></tr><tr><td>chat_history</td><td>List[Data]</td><td>可选的代理聊天记录</td></tr><tr><td>tools</td><td>List[Tool]</td><td>代理可用的工具列表</td></tr></tbody></table><h3 id="outputs-10" tabindex="-1">输出 <a class="header-anchor" href="#outputs-10" aria-label="Permalink to &quot;输出 {#outputs-10}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>agent</td><td>AgentExecutor</td><td>调用工具的Agent实例</td></tr></tbody></table><h2 id="vector-store-agent" tabindex="-1">Vector Store Agent <a class="header-anchor" href="#vector-store-agent" aria-label="Permalink to &quot;Vector Store Agent&quot;">​</a></h2><p>该组件使用 LangChain 创建一个 Vector Store Agent（向量存储代理）。</p><h3 id="inputs-9" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-9" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>llm</td><td>LanguageModel</td><td>用于代理的语言模型</td></tr><tr><td>vectorstore</td><td>VectorStoreInfo</td><td>代理用于的向量存储信息</td></tr></tbody></table><h3 id="输出-2" tabindex="-1">输出 <a class="header-anchor" href="#输出-2" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>agent</td><td>AgentExecutor</td><td><code>Vector Store Agent</code> 实例</td></tr></tbody></table><h2 id="vector-store-router-agent" tabindex="-1">Vector Store Router Agent <a class="header-anchor" href="#vector-store-router-agent" aria-label="Permalink to &quot;Vector Store Router Agent&quot;">​</a></h2><p>该组件使用 LangChain 创建一个 Vector Store Router Agent（向量存储路由代理）。</p><h3 id="输入-2" tabindex="-1">输入 <a class="header-anchor" href="#输入-2" aria-label="Permalink to &quot;输入&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>llm</td><td>LanguageModel</td><td>用于代理的语言模型</td></tr><tr><td>vectorstores</td><td>List[VectorStoreInfo]</td><td>代理在各向量存储之间进行路由的信息列表</td></tr></tbody></table><h3 id="outputs-8" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-8" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>agent</td><td>AgentExecutor</td><td>Vector Store Router Agent 实例</td></tr></tbody></table><h2 id="xml-agent" tabindex="-1">XML Agent <a class="header-anchor" href="#xml-agent" aria-label="Permalink to &quot;XML Agent&quot;">​</a></h2><p>该组件使用 LangChain 创建一个 XML Agent。</p><p>该代理使用 XML 格式为语言模型提供工具指令。</p><h3 id="inputs-10" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-10" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>llm</td><td>LanguageModel</td><td>用于代理的语言模型</td></tr><tr><td>user_prompt</td><td>String</td><td>用于代理的自定义提示模板（包含XML格式说明）</td></tr><tr><td>tools</td><td>List[Tool]</td><td>代理可用的工具列表</td></tr></tbody></table><h3 id="outputs-9" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-9" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>agent</td><td>AgentExecutor</td><td>XML Agent 实例</td></tr></tbody></table>',102)]))}const m=a(h,[["render",n]]);export{g as __pageData,m as default};
